package com.personal.assistant.module.ai.provider;import com.fasterxml.jackson.databind.*;import com.personal.assistant.module.ai.entity.AiProviderConfig;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.util.*;
@Component public class DeepSeekAiProvider implements AiProvider{private final RestClient.Builder clients;private final ObjectMapper json;public DeepSeekAiProvider(RestClient.Builder clients,ObjectMapper json){this.clients=clients;this.json=json;}public String type(){return "DEEPSEEK";}public String complete(AiProviderConfig config,String apiKey,String systemPrompt,String input){String base=config.getBaseUrl()==null||config.getBaseUrl().isBlank()?"https://api.deepseek.com":config.getBaseUrl();Map<String,Object>body=Map.of("model",config.getModelName(),"messages",List.of(Map.of("role","system","content",systemPrompt),Map.of("role","user","content",input)),"temperature",0.2);String raw=clients.baseUrl(base).defaultHeader(HttpHeaders.AUTHORIZATION,"Bearer "+apiKey).build().post().uri("/chat/completions").contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(String.class);try{return json.readTree(raw).path("choices").path(0).path("message").path("content").asText();}catch(Exception e){throw new IllegalStateException("AI 响应解析失败",e);}}}
